source.searchUrl:
@js:
burl = source.getKey().match(/([^#]*)/)[1];
url = burl+"/e/search/";
body = "show=title%2Cnewstext&keyboard="+key;
$ = java.post(url+"index.php",body,{}).headers();
uri = $.Location||$.location;
url+=String(uri).replace('?','<?,index.php?page={{page-1}}&>');

