@js:
page=result.match(/<b>(\d*)<\/b>\/<b>(\d+)<\/b>/)[2];
//java.log(page)
list=[];
list.push({text:'第1页',href:baseUrl});
if(page>=2){
for(var i=2;i<=page;i++){
href1=baseUrl.replace(/.html/,'')+'_'+i+'.html';
list.push({text:'第'+i+'页',href:href1});
}
}
